if (order is null || order.Status == OrderStatus.Cancelled) return false;
if (order.Items is null || order.Items.Count == 0) return false;
return order.Items.All(x => x.Quantity > 0);

if (k <= 0 || k > values.Length) throw new ArgumentOutOfRangeException(nameof(k));
var sum = 0;
for (var i = 0; i < k; i++) sum += values[i];
var max = sum;
for (var i = k; i < values.Length; i++) { sum += values[i] - values[i-k]; if (sum > max) max = sum; }
return max;
